package com.justjava.humanresource.employeeexit.service; import com.justjava.humanresource.employeeexit.dto.*; import com.justjava.humanresource.employeeexit.enums.*; import com.justjava.humanresource.employeeexit.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.time.LocalDate; import java.util.*;
@Service @RequiredArgsConstructor public class EmployeeExitReadinessService {private final EmployeeExitService exits;private final ExitClearanceItemRepository clearances;private final ExitAssetReturnRepository assets;private final EmployeeExitDocumentRepository documents;private final ExitSettlementRepository settlements;private final ExitAccessActionRepository access;
 public ExitReadinessResult validate(Long id){var x=exits.require(id);List<ExitReadinessBlocker>b=new ArrayList<>();if(clearances.existsByExitCaseIdAndStatusNotIn(id,List.of(ClearanceStatus.CLEARED,ClearanceStatus.CLEARED_WITH_EXCEPTION,ClearanceStatus.WAIVED)))b.add(block(ExitReadinessBlocker.Category.PENDING_CLEARANCE,"One or more clearance workstreams are pending."));if(assets.findByExitCaseIdOrderByAssetName(id).stream().anyMatch(a->a.getDisposition()==AssetDisposition.PENDING))b.add(block(ExitReadinessBlocker.Category.PENDING_ASSET_DISPOSITION,"An assigned asset has no final disposition."));ExitDocumentType required=x.getExitType()==ExitType.RESIGNATION?ExitDocumentType.RESIGNATION_LETTER:(x.getExitType()==ExitType.TERMINATION?ExitDocumentType.TERMINATION_LETTER:null);if(required!=null&&!documents.existsByExitCaseIdAndDocumentType(id,required))b.add(block(ExitReadinessBlocker.Category.MISSING_REQUIRED_DOCUMENT,"Required document is missing: "+required));var s=settlements.findFirstByExitCaseIdOrderBySettlementVersionDesc(id);if(s.isEmpty()||s.get().getStatus().ordinal()<SettlementStatus.APPROVED.ordinal())b.add(block(ExitReadinessBlocker.Category.SETTLEMENT_NOT_APPROVED,"Final settlement is not approved."));else if(s.get().getStatus()==SettlementStatus.APPROVED)b.add(block(ExitReadinessBlocker.Category.SETTLEMENT_NOT_POSTED,"Approved settlement has not been posted to payroll."));if(x.getEffectiveExitDate()!=null&&x.getEffectiveExitDate().isAfter(LocalDate.now()))b.add(block(ExitReadinessBlocker.Category.EFFECTIVE_DATE_NOT_REACHED,"Effective exit date has not arrived."));if(x.getAccessRevokedAt()==null)b.add(block(ExitReadinessBlocker.Category.ACCESS_REVOCATION_PENDING,"Access revocation is pending."));boolean operational=b.stream().noneMatch(v->v.category()!=ExitReadinessBlocker.Category.EFFECTIVE_DATE_NOT_REACHED&&v.category()!=ExitReadinessBlocker.Category.ACCESS_REVOCATION_PENDING);return new ExitReadinessResult(operational,List.copyOf(b));}
 private ExitReadinessBlocker block(ExitReadinessBlocker.Category c,String m){return new ExitReadinessBlocker(c,m);}}
